package studio.jiayu.neoagent;
import android.app.Activity;import android.graphics.*;import android.os.*;import android.view.*;import android.view.accessibility.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.concurrent.*;
/** Owned native screen only. Tests full-display perimeter, no centre pixels and input pass-through. */
final class EffectsContracts {
 static void start(Activity a){LinearLayout box=new LinearLayout(a);box.setPadding(40,180,40,40);box.setBackgroundColor(0xFFF4F6FA);Button button=new Button(a);button.setText("边缘特效透传测试");box.addView(button);TextView note=new TextView(a);note.setText("蓝色流光 · 四边连续贴合 · 中央透明\nJIAYU STUDIO · StepX Neo 研究所");note.setTextColor(0xFF343A47);note.setTextSize(16);box.addView(note);a.setContentView(box);java.util.concurrent.atomic.AtomicInteger clicked=new java.util.concurrent.atomic.AtomicInteger();button.setOnClickListener(v->clicked.incrementAndGet());new Handler().postDelayed(()->new Thread(()->run(a,button,clicked)).start(),700);}
 static void run(Activity a,Button button,java.util.concurrent.atomic.AtomicInteger clicked){ControlService s=ControlService.instance;JSONObject result=new JSONObject();int passed=0;Bitmap first=null,second=null;String priorConsent="";boolean consentSaved=false,ownLease=false;try{
  if(s==null||!s.connected||s.busy())throw new Exception("Runtime not idle");s.ui(()->{if(s.busy())throw new Exception("Runtime no longer idle");s.workflow=null;s.allowed=a.getPackageName();s.runConfig=null;s.task="蓝色边缘本地测试，无需模型";s.trace=new StringBuilder();s.status="蓝色边缘预览";s.runId="";s.ownerSession="";s.running=true;s.paused=false;s.generation=s.ownership.start();s.runtimeHealth.phase("starting");s.showOverlay();return true;});ownLease=true;Thread.sleep(600);
  yes(s.ui(()->{NativeWindowState state=NativeWindowState.inspect(s);return state.expected&&!state.covered;}),"Owned fixture lost foreground before testing");
  Rect frame=s.ui(()->{if(s.effects==null)return null;int[] origin=new int[2];s.effects.getLocationOnScreen(origin);return new Rect(origin[0],origin[1],origin[0]+s.effects.getWidth(),origin[1]+s.effects.getHeight());});android.util.DisplayMetrics dm=s.screenMetrics();result.put("view_frame",frame==null?"missing":frame.toShortString()).put("expected_display",dm.widthPixels+"x"+dm.heightPixels);yes(frame!=null&&frame.left==0&&frame.top==0&&frame.right==dm.widthPixels&&frame.bottom==dm.heightPixels,"Overlay does not cover exact display");passed++;
  first=s.ui(()->{Bitmap b=Bitmap.createBitmap(s.effects.getWidth(),s.effects.getHeight(),Bitmap.Config.ARGB_8888);s.effects.drawFrame(new Canvas(b),.5f);return b;});int w=first.getWidth(),h=first.getHeight();
  for(int[] point:new int[][]{{w/2,0},{w-1,h/2},{w/2,h-1},{0,h/2}}){int color=first.getPixel(point[0],point[1]);yes(Color.alpha(color)>0&&Color.blue(color)>Color.red(color),"Missing blue perimeter");passed++;}
  yes(first.getPixel(w/2,h/2)==Color.TRANSPARENT,"Centre not transparent");passed++;
  s.ui(()->{s.effects.appBounds(new Rect(100,200,w-100,h-200));s.effects.target(w/2,h/2,"tap");return true;});Thread.sleep(220);second=s.ui(()->{Bitmap b=Bitmap.createBitmap(s.effects.getWidth(),s.effects.getHeight(),Bitmap.Config.ARGB_8888);s.effects.drawFrame(new Canvas(b),.5f);return b;});yes(first.sameAs(second),"App bounds or touch changed perimeter");passed++;
  s.ui(()->{Bitmap low=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888),high=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);s.effects.drawFrame(new Canvas(low),0);s.effects.drawFrame(new Canvas(high),1);yes(!low.sameAs(high),"Breathing halo not visible");yes(low.getPixel(w/2,h/2)==0&&high.getPixel(w/2,h/2)==0,"Pulse painted centre");for(int[] pt:new int[][]{{w/2,0},{w-1,h/2},{w/2,h-1},{0,h/2}})yes(Color.alpha(low.getPixel(pt[0],pt[1]))>0,"Pulse extinguished edge");low.recycle();high.recycle();return true;});passed++;
  s.ui(()->{Bitmap x=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888),y=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);s.effects.drawFrame(new Canvas(x),.7f,.1f);s.effects.drawFrame(new Canvas(y),.7f,.4f);yes(!x.sameAs(y),"No travelling edge light");yes(x.getPixel(w/2,h/2)==0&&y.getPixel(w/2,h/2)==0,"Flow painted centre");x.recycle();y.recycle();return true;});passed++;
  passed+=edgeComparisons(s,result,w,h);
  yes(awaitOwnedButton(a,s,button,3500),"Owned fixture button not ready after Activity transition");passed++;
  int[] centre=s.ui(()->{int[] xy=new int[2];button.getLocationOnScreen(xy);return new int[]{xy[0]+button.getWidth()/2,xy[1]+button.getHeight()/2};});CompletableFuture<Boolean> gesture=new CompletableFuture<>();s.ui(()->{NativeWindowState state=NativeWindowState.inspect(s);yes(state.expected&&!state.covered,"Owned fixture lost foreground before gesture");Path path=new Path();path.moveTo(centre[0],centre[1]);s.dispatchGesture(new android.accessibilityservice.GestureDescription.Builder().addStroke(new android.accessibilityservice.GestureDescription.StrokeDescription(path,0,100)).build(),new android.accessibilityservice.AccessibilityService.GestureResultCallback(){public void onCompleted(android.accessibilityservice.GestureDescription d){gesture.complete(true);}public void onCancelled(android.accessibilityservice.GestureDescription d){gesture.complete(false);}},new Handler(Looper.getMainLooper()));return true;});yes(gesture.get(3,TimeUnit.SECONDS)&&clicked.get()==1,"Overlay consumed touch");passed++;
  // Exercise the real guarded gesture while our movable capsule covers the owned button.
  priorConsent=new Vault(a).get(RoutineAccess.KEY);consentSaved=true;Config fixture=new Config();fixture.endpoint="https://fixture.invalid/v1";fixture.key="LOCAL_FIXTURE";fixture.vision=true;new RoutineAccess(a).approve(fixture,java.util.Collections.singletonList(a.getPackageName()));s.runConfig=fixture;
  s.ui(()->{Rect b=s.controlBar.bounds();yes(b!=null,"Capsule unavailable");WindowManager.LayoutParams layout=(WindowManager.LayoutParams)s.controlBar.view.getLayoutParams();layout.x+=Math.max(s.dp(7),centre[0]-b.width()/2)-b.left;layout.y+=Math.max(s.dp(28),centre[1]-b.height()/2)-b.top;((WindowManager)a.getSystemService(Activity.WINDOW_SERVICE)).updateViewLayout(s.controlBar.view,layout);return true;});Thread.sleep(250);
  yes(s.ui(()->{Rect b=s.controlBar.bounds();return b!=null&&b.contains(centre[0],centre[1]);}),"Capsule fixture did not obstruct the target");passed++;
  yes(awaitOwnedButton(a,s,button,3500),"Owned fixture button not ready before guarded gesture");passed++;
  ControlService.Observation observation=s.observe(true,s.generation);int target=-1;for(java.util.Map.Entry<Integer,AccessibilityNodeInfo> entry:observation.targets.entrySet())if("边缘特效透传测试".contentEquals(entry.getValue().getText()))target=entry.getKey();yes(target>=0,"Covered owned target lost system semantics");passed++;
  s.execute(Action.parse(new JSONObject().put("action","tap").put("id",target).toString()),s.generation,observation);yes(clicked.get()==2,"Capsule blocked guarded native gesture instead of moving aside");passed++;
  result.put("guarded_capsule_avoidance",true);
  try(FileOutputStream out=a.openFileOutput("blue-edges-render.png",0)){first.compress(Bitmap.CompressFormat.PNG,100,out);}Bitmap preview=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);Canvas previewCanvas=new Canvas(preview);previewCanvas.drawColor(0xFF202126);previewCanvas.drawBitmap(first,0,0,null);try(FileOutputStream out=a.openFileOutput("blue-edges-preview.png",0)){preview.compress(Bitmap.CompressFormat.PNG,100,out);}preview.recycle();result.put("success",true).put("display_frame_exact",true).put("all_four_blue_edges",true).put("centre_transparent",true).put("continuous_edge_breathing",true).put("period_ms",3600).put("flow_period_ms",8000).put("perimeter_flow",true).put("halo_cached",true).put("hardware_accelerated",s.effects.isHardwareAccelerated()).put("touch_pass_through",true);
 }catch(Throwable failure){try{result.put("success",false).put("failure",failure.getMessage());}catch(Exception ignored){}}
 finally{if(consentSaved)try{if(priorConsent.isEmpty())new Vault(a).remove(RoutineAccess.KEY);else new Vault(a).put(RoutineAccess.KEY,priorConsent);result.put("routine_access_restored",priorConsent.equals(new Vault(a).get(RoutineAccess.KEY)));}catch(Exception ignored){}if(s!=null&&ownLease)s.runtimeHealth.phase("waiting");if(result.optBoolean("success")&&"effects_preview".equals(a.getIntent().getStringExtra("mode")))try{Thread.sleep(25000);}catch(InterruptedException ignored){}if(first!=null)first.recycle();if(second!=null)second.recycle();if(s!=null&&ownLease)s.stop("蓝色边缘回归结束");try{result.put("passed",passed).put("real_network_calls",0).put("third_party_actions",0).put("sampledAt",System.currentTimeMillis());try(FileOutputStream out=a.openFileOutput("effects-contracts.json",0)){out.write(result.toString(2).getBytes("UTF-8"));}}catch(Exception ignored){}new Handler(Looper.getMainLooper()).post(a::finish);}
 }
 static boolean awaitOwnedButton(Activity a,ControlService s,Button button,long timeout)throws Exception{
  long until=SystemClock.uptimeMillis()+timeout;while(SystemClock.uptimeMillis()<until){boolean ready=s.ui(()->{
   if(a.isFinishing()||a.isDestroyed()||!a.hasWindowFocus()||!button.isShown())return false;AccessibilityNodeInfo root=s.getRootInActiveWindow();if(root==null||!a.getPackageName().contentEquals(root.getPackageName()))return false;int[] origin=new int[2];button.getLocationOnScreen(origin);Rect wanted=new Rect(origin[0],origin[1],origin[0]+button.getWidth(),origin[1]+button.getHeight());
   for(AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText(button.getText().toString()))if(node.isVisibleToUser()&&button.getText().toString().contentEquals(node.getText())){Rect actual=new Rect();node.getBoundsInScreen(actual);if(actual.equals(wanted))return true;}return false;
  });if(ready)return true;Thread.sleep(80);}return false;
 }
 static Bitmap composite(ControlService s,int width,int height,int background,int button,int x,int y,float strength,float phase,boolean popup){
  Bitmap bitmap=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.drawColor(background);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setColor(button);canvas.drawRoundRect(new RectF(x-s.dp(14),y-s.dp(18),x+s.dp(14),y+s.dp(18)),s.dp(3),s.dp(3),p);p.setColor(Color.WHITE);p.setTextSize(s.dp(10));p.setTextAlign(Paint.Align.CENTER);canvas.drawText("搜索",x,y+s.dp(3),p);if(popup){p.setColor(0xff9c42b5);canvas.drawRect(width*.20f,height*.42f,width*.80f,height*.73f,p);}s.effects.drawFrame(canvas,strength,phase);return bitmap;
 }
 static int edgeComparisons(ControlService s,JSONObject result,int width,int height)throws Exception{return s.ui(()->{
  JSONArray cases=new JSONArray();int checks=0;for(int background:new int[]{Color.BLACK,Color.WHITE})for(boolean right:new boolean[]{true,false}){
   int x=right?width-s.dp(20):s.dp(20),y=height/3;Bitmap low=null,high=null,replaced=null,popup=null;
   try{low=composite(s,width,height,background,0xff07c160,x,y,0f,.07f,false);high=composite(s,width,height,background,0xff07c160,x,y,1f,.53f,false);replaced=composite(s,width,height,background,0xffd93846,x,y,1f,.53f,false);popup=composite(s,width,height,background,0xff07c160,x,y,1f,.53f,true);
    java.util.ArrayList<Rect> masks=new java.util.ArrayList<>();s.addEffectMasks(masks,width,height);yes(!ControlService.visualPathMasked(masks,x,y,x,y),"20dp edge button centre still masked");checks++;
    long now=SystemClock.uptimeMillis();Rect whole=new Rect(0,0,width,height);VisualActionRules.Frame original=ControlService.visualActionFrame(low,whole,masks,now-10);VisualActionRules.Verdict glow=VisualActionRules.compare(original,ControlService.visualActionFrame(high,whole,masks,now-10),x,y,x,y,s.dp(24),now);
    JSONObject item=new JSONObject().put("background",background==Color.BLACK?"black":"white").put("edge",right?"right":"left").put("button_edge_distance_dp",20).put("effect_mask_dp",VisualActionRules.EFFECT_MASK_DP).put("low_strength",0).put("high_strength",1).put("low_phase",.07).put("high_phase",.53).put("glow_only_allowed",glow.allowed).put("glow_reason",glow.reason).put("global_changed_samples",glow.globalChanged).put("local_changed_samples",glow.localChanged);cases.put(item);result.put("edge_button_visual_cases",cases);
    yes(glow.allowed,"Soft glow rejected "+item.toString());checks++;
    VisualActionRules.Verdict changed=VisualActionRules.compare(original,ControlService.visualActionFrame(replaced,whole,masks,now-10),x,y,x,y,s.dp(24),now);yes(!changed.allowed,"Actual edge button color replacement accepted");checks++;item.put("real_button_change_rejected",true);
    VisualActionRules.Verdict modal=VisualActionRules.compare(original,ControlService.visualActionFrame(popup,whole,masks,now-10),x,y,x,y,s.dp(24),now);yes(!modal.allowed,"New popup accepted in edge scene");checks++;item.put("new_popup_rejected",true);
   }finally{if(low!=null)low.recycle();if(high!=null)high.recycle();if(replaced!=null)replaced.recycle();if(popup!=null)popup.recycle();}
  }result.put("edge_visual_thresholds_unchanged",true).put("control_effect_rendering_changed",false);return checks;
 });}
 static void yes(boolean ok,String reason)throws Exception{if(!ok)throw new Exception(reason);}
}
